package.path="/?.lua;/?/init.lua;"..package.path;local a=require("tools.beaconupdate")local b=require("beacon.update")local c="/eh2_beacon_update.tbl"local function d()if not fs.exists(c)or fs.isDir(c)then return{}end;local e=fs.open(c,"r")local f=e.readAll()e.close()local g=textutils.unserialise(f or"")return type(g)=="table"and g or{}end;local function h(g)local e=fs.open(c,"w")e.write(textutils.serialise(g))e.close()end;local function i()for j,k in ipairs(peripheral.getNames())do if peripheral.getType(k)=="modem"then local l=peripheral.wrap(k)if l.isWireless and l.isWireless()then return l end end end;return nil end;local m=d()m.channel=m.channel or 65000;if not b.validToken(m.updateToken)then write("Set the shared update secret (must match the beacons): ")local n=read()n=tostring(n or""):gsub("%s","")if n==""then print("no token entered -- aborting.")return end;m.updateToken=n;h(m)end;local o=i()if not o then print("no wireless/ender modem found.")return end;o.open(m.channel)local p;local q=a.run({token=m.updateToken,channel=m.channel,transmit=function(r,s,t)o.transmit(r,s,t)end,pull=function(u)if p==nil then p=os.clock()+u end;local v=os.startTimer(p-os.clock())while true do local w=p-os.clock()if w<=0 then os.cancelTimer(v)return nil end;local x={os.pullEvent()}if x[1]=="modem_message"then local e=b.decode(x[5])if e and e.k==b.ACK_KIND then os.cancelTimer(v)return e.id end elseif x[1]=="timer"and x[2]==v then return nil end end end})if not q.ok then print(q.err)return end;if#q.responders==0 then print("no beacons answered (asleep/unloaded, or wrong token/channel).")else print("updating: "..table.concat(q.responders,", "))end